// Tổng hợp câu hỏi thường gặp, tự diễn giải theo kiến thức phổ biến — không sao chép nguyên văn nguồn nào.
export const FAQ_ITEMS: FaqItem[] = [
  // --- kinh-dich ---
  { id: 1, category: "kinh-dich", question: "Quẻ biến là gì?", answer: "Quẻ biến là quẻ hình thành sau khi xét các hào động và biến đổi chúng. Theo cách luận phổ biến, quẻ ban đầu mô tả hoàn cảnh hiện tại, còn quẻ biến gợi ý xu hướng hoặc trạng thái tiếp theo.", topic: "quẻ biến" },
  { id: 2, category: "kinh-dich", question: "Hào động là gì?", answer: "Hào động là hào được xác định có tính biến trong một lần lập quẻ. Hào động thường được dùng để suy ra quẻ biến và làm rõ điểm đang thay đổi trong sự việc.", topic: "hào động" },
  { id: 3, category: "kinh-dich", question: "Quẻ chủ là gì?", answer: "Quẻ chủ thường chỉ quẻ được lập ban đầu trước khi xét biến hào. Nó được dùng làm nền để xem tổng thể vấn đề được hỏi.", topic: "quẻ chủ" },
  { id: 4, category: "kinh-dich", question: "Quẻ hỗ là gì?", answer: "Quẻ hỗ là quẻ được lấy từ các hào ở giữa của quẻ chủ theo một phương pháp quy ước. Nó thường được dùng để tham khảo thêm diễn biến hoặc nội tình của sự việc.", topic: "quẻ hỗ" },
  { id: 5, category: "kinh-dich", question: "Bát quái gồm những quẻ nào?", answer: "Bát quái gồm Càn, Khảm, Cấn, Chấn, Tốn, Ly, Khôn và Đoài. Mỗi quẻ có tượng, tính chất và ý nghĩa biểu trưng riêng.", topic: "Bát quái" },
  { id: 6, category: "kinh-dich", question: "Quẻ Càn tượng trưng cho gì?", answer: "Theo hệ thống tượng quẻ, Càn thường gắn với Trời, tính cương kiện, chủ động và sáng tạo. Khi luận cụ thể vẫn cần xét hào, vị trí và hoàn cảnh câu hỏi.", topic: "quẻ Càn" },
  { id: 7, category: "kinh-dich", question: "Quẻ Khôn tượng trưng cho gì?", answer: "Khôn thường gắn với Đất, tính tiếp nhận, nuôi dưỡng và thuận theo. Ý nghĩa tốt hay xấu không nên tách khỏi toàn bộ cấu trúc quẻ.", topic: "quẻ Khôn" },
  { id: 8, category: "kinh-dich", question: "Quẻ Khảm tượng trưng cho gì?", answer: "Khảm thường gắn với Nước, chiều sâu, hiểm trở và sự lưu động. Trong luận đoán dân gian, nó có thể gợi hoàn cảnh cần thận trọng hoặc thích ứng.", topic: "quẻ Khảm" },
  { id: 9, category: "kinh-dich", question: "Quẻ Ly tượng trưng cho gì?", answer: "Ly thường gắn với Lửa, ánh sáng, sự sáng rõ và nhận thức. Tùy câu hỏi, tượng Ly có thể được hiểu theo nhiều lớp nghĩa khác nhau.", topic: "quẻ Ly" },
  { id: 10, category: "kinh-dich", question: "Quẻ Chấn tượng trưng cho gì?", answer: "Chấn thường gắn với Sấm, sự khởi động, chuyển biến và động lực mạnh. Nó có thể biểu thị một sự việc bắt đầu hoặc biến động nhanh.", topic: "quẻ Chấn" },
  { id: 11, category: "kinh-dich", question: "Quẻ Tốn tượng trưng cho gì?", answer: "Tốn thường gắn với Gió, sự thâm nhập, mềm dẻo và lan tỏa. Trong dân gian, tượng Tốn thường được liên hệ với tiến triển từng bước.", topic: "quẻ Tốn" },
  { id: 12, category: "kinh-dich", question: "Quẻ Đoài tượng trưng cho gì?", answer: "Đoài thường gắn với Đầm, niềm vui, giao tiếp và sự hòa duyệt. Ý nghĩa cụ thể còn phụ thuộc vào quẻ đi cùng và hào động.", topic: "quẻ Đoài" },
  { id: 13, category: "kinh-dich", question: "64 quẻ Kinh Dịch được tạo thành thế nào?", answer: "64 quẻ hình thành từ việc ghép hai quái đơn, một ở trên và một ở dưới, tạo thành quái kép. Mỗi quẻ có sáu hào để diễn tả nhiều trạng thái biến hóa.", topic: "64 quẻ" },
  { id: 14, category: "kinh-dich", question: "Một quẻ có bao nhiêu hào?", answer: "Mỗi quẻ kép có sáu hào, được đọc từ dưới lên trên. Các hào có vị trí và tính chất khác nhau khi luận.", topic: "lục hào" },
  { id: 15, category: "kinh-dich", question: "Hào âm và hào dương khác nhau thế nào?", answer: "Hào dương thường được biểu diễn bằng một nét liền, còn hào âm bằng một nét đứt. Đây là hai dạng cơ bản tạo nên các quẻ.", topic: "âm dương" },
  { id: 16, category: "kinh-dich", question: "Tam đồng pháp là gì?", answer: "Tam đồng pháp là cách gieo quẻ dùng ba đồng tiền, dựa vào mặt quy ước của từng đồng để xác định âm, dương và hào động. Cách quy ước cụ thể có thể khác giữa các trường phái.", topic: "tam đồng pháp" },
  { id: 17, category: "kinh-dich", question: "Gieo quẻ bằng đồng tiền có đáng tin không?", answer: "Trong truyền thống dân gian, gieo quẻ được xem là một phương thức lấy tượng để tham khảo. Không có cơ sở khoa học để xem kết quả như dự báo chắc chắn về tương lai.", topic: "gieo quẻ" },
  { id: 18, category: "kinh-dich", question: "Có thể gieo quẻ bằng ứng dụng không?", answer: "Có thể dùng ứng dụng để mô phỏng quy trình gieo quẻ nếu quy tắc được thiết lập rõ ràng. Tuy nhiên, nên xem kết quả như tư liệu tham khảo chứ không phải kết luận tuyệt đối.", topic: "gieo quẻ online" },
  { id: 19, category: "kinh-dich", question: "Gieo quẻ vào giờ nào là tốt nhất?", answer: "Không có một giờ duy nhất được mọi trường phái công nhận là tốt nhất cho mọi câu hỏi. Theo quan niệm phổ biến, nên chọn lúc tâm trí tương đối bình tĩnh và câu hỏi rõ ràng.", topic: "giờ gieo quẻ" },
  { id: 20, category: "kinh-dich", question: "Có nên gieo quẻ khi đang quá lo lắng?", answer: "Theo kinh nghiệm dân gian, trạng thái quá căng thẳng dễ khiến người hỏi liên tục đổi câu hỏi hoặc gieo lại. Tốt hơn là bình tâm, xác định vấn đề rồi mới lập quẻ.", topic: "tâm thế gieo quẻ" },
  { id: 21, category: "kinh-dich", question: "Nên hỏi Kinh Dịch như thế nào?", answer: "Nên đặt câu hỏi cụ thể, có phạm vi và thời điểm tương đối rõ. Câu hỏi càng rõ thì việc diễn giải biểu tượng càng dễ thống nhất.", topic: "cách đặt câu hỏi" },
  { id: 22, category: "kinh-dich", question: "Có nên hỏi một vấn đề nhiều lần?", answer: "Thường không nên liên tục gieo lại chỉ vì không thích kết quả. Nếu hoàn cảnh chưa thay đổi, nhiều lần gieo có thể làm người hỏi càng khó phân biệt thông tin nào cần tham khảo.", topic: "gieo quẻ nhiều lần" },
  { id: 23, category: "kinh-dich", question: "Nên gieo quẻ bao nhiêu lần một ngày?", answer: "Không có con số bắt buộc chung, nhưng cách thực hành thận trọng là chỉ gieo khi có một vấn đề thực sự cần xem xét. Việc lặp lại quá nhiều lần trong cùng một chuyện thường không được khuyến khích.", topic: "số lần gieo quẻ" },
  { id: 24, category: "kinh-dich", question: "Quẻ xấu có đáng lo không?", answer: "Theo cách tiếp cận truyền thống, quẻ bất lợi thường được xem như lời cảnh báo về điều kiện hoặc xu hướng, không phải bản án cố định. Có thể dùng nó để điều chỉnh hành động và giảm rủi ro.", topic: "quẻ xấu" },
  { id: 25, category: "kinh-dich", question: "Quẻ tốt có đảm bảo chắc chắn thành công không?", answer: "Không. Quẻ thuận lợi chỉ nên được hiểu là dấu hiệu tích cực theo hệ thống biểu tượng; kết quả thực tế còn phụ thuộc hành động, hoàn cảnh và nhiều yếu tố khác.", topic: "quẻ tốt" },
  { id: 26, category: "kinh-dich", question: "Kinh Dịch có dự đoán chính xác tương lai không?", answer: "Kinh Dịch là một hệ thống triết học và biểu tượng cổ, được nhiều người dùng để suy ngẫm về biến đổi. Không nên xem nó là phương pháp dự báo chắc chắn theo tiêu chuẩn khoa học hiện đại.", topic: "dự đoán tương lai" },
  { id: 27, category: "kinh-dich", question: "Kinh Dịch có phải bói toán không?", answer: "Kinh Dịch có lịch sử gắn với việc lập quẻ và dự đoán, nhưng nội dung của nó rộng hơn bói toán, bao gồm tư tưởng về biến dịch, âm dương và cách ứng xử. Cách sử dụng hiện nay rất đa dạng.", topic: "Kinh Dịch và bói toán" },
  { id: 28, category: "kinh-dich", question: "Quẻ có thể thay đổi không?", answer: "Quẻ đã lập không tự thay đổi, nhưng cách hiểu và hoàn cảnh thực tế có thể thay đổi. Một lần lập quẻ mới chỉ có ý nghĩa khi câu hỏi hoặc điều kiện đã thực sự khác.", topic: "quẻ và hoàn cảnh" },
  { id: 29, category: "kinh-dich", question: "Thế và Ứng là gì?", answer: "Thế và Ứng là các vị trí được dùng trong một số phương pháp lục hào để phân biệt phía người hỏi và phía đối tượng/sự việc. Cách an Thế, Ứng phụ thuộc phương pháp lập quẻ.", topic: "Thế Ứng" },
  { id: 30, category: "kinh-dich", question: "Lục thân là gì?", answer: "Lục thân là hệ thống quan hệ tượng trưng như Phụ mẫu, Huynh đệ, Thê tài, Quan quỷ và Tử tôn trong lục hào. Chúng được dùng để gán ý nghĩa cho các hào theo câu hỏi.", topic: "lục thân" },
  { id: 31, category: "kinh-dich", question: "Ngũ hành sinh khắc trong Kinh Dịch dùng để làm gì?", answer: "Ngũ hành có thể được dùng trong một số phương pháp luận quẻ để xét quan hệ sinh, khắc, đồng hành giữa các yếu tố. Đây là lớp diễn giải thuộc truyền thống mệnh lý, không phải nội dung duy nhất của Kinh Dịch.", topic: "ngũ hành sinh khắc" },
  { id: 32, category: "kinh-dich", question: "Quẻ Phục nói về điều gì?", answer: "Quẻ Phục thường được liên hệ với ý niệm trở lại, hồi phục hoặc quay về đúng hướng. Cần xét thêm hào và hoàn cảnh để tránh hiểu theo nghĩa tuyệt đối.", topic: "quẻ Phục" },
  { id: 33, category: "kinh-dich", question: "Quẻ Thái và Quẻ Bĩ khác nhau thế nào?", answer: "Thái thường biểu trưng cho trạng thái giao hòa, thông đạt; Bĩ thường biểu trưng cho bế tắc hoặc không thông. Đây là ý nghĩa tượng trưng, không phải khẳng định chắc chắn về vận mệnh.", topic: "quẻ Thái, quẻ Bĩ" },
  { id: 34, category: "kinh-dich", question: "Quẻ Ký Tế và Vị Tế khác nhau thế nào?", answer: "Ký Tế thường gợi trạng thái đã qua một bước hoàn thành nhưng vẫn cần giữ cân bằng. Vị Tế thường gợi việc chưa hoàn tất và còn phải tiếp tục xử lý.", topic: "quẻ Ký Tế, quẻ Vị Tế" },
  { id: 35, category: "kinh-dich", question: "Có nên dùng Kinh Dịch để quyết định chuyện y tế?", answer: "Không nên dùng quẻ thay cho chẩn đoán hoặc điều trị y khoa. Với vấn đề sức khỏe, quẻ chỉ có thể được xem như một hình thức tham khảo tinh thần nếu người dùng muốn.", topic: "Kinh Dịch và sức khỏe" },
  { id: 36, category: "kinh-dich", question: "Có nên dùng Kinh Dịch để quyết định đầu tư?", answer: "Không nên xem quẻ là công cụ thay thế phân tích tài chính, pháp lý hoặc quản trị rủi ro. Nếu tham khảo, nên coi quẻ như một góc nhìn biểu tượng và vẫn dựa trên dữ liệu thực tế.", topic: "Kinh Dịch và tài chính" },
  { id: 37, category: "kinh-dich", question: "Quẻ biến có phải luôn quan trọng hơn quẻ chủ?", answer: "Không. Nhiều cách luận xem quẻ chủ là nền tảng và quẻ biến là phần bổ sung về xu hướng thay đổi. Trọng tâm cụ thể phụ thuộc phương pháp và câu hỏi.", topic: "quẻ chủ, quẻ biến" },
  { id: 38, category: "kinh-dich", question: "Nếu không có hào động thì luận thế nào?", answer: "Một số phương pháp xem quẻ không động sẽ tập trung vào quẻ chủ và các quan hệ nội tại của quẻ. Không nhất thiết phải có hào động mới có thể diễn giải.", topic: "hào tĩnh" },
  { id: 39, category: "kinh-dich", question: "Có thể tự học Kinh Dịch từ các quẻ cơ bản không?", answer: "Có. Người mới thường nên bắt đầu từ âm dương, Bát quái, tượng quẻ và cấu trúc sáu hào trước khi học các hệ thống luận phức tạp hơn.", topic: "tự học Kinh Dịch" },
  { id: 40, category: "kinh-dich", question: "Điều quan trọng nhất khi đọc một quẻ là gì?", answer: "Nên xác định rõ câu hỏi, phương pháp lập quẻ và các quy tắc luận đang sử dụng. Sau đó mới xét tổng thể quẻ thay vì chỉ nhìn một biểu tượng rồi kết luận.", topic: "phương pháp luận quẻ" },
  { id: 41, category: "kinh-dich", question: "Kinh Dịch có phải là mê tín không?", answer: "Việc xem quẻ như một phương thức dự đoán tuyệt đối có thể dẫn đến cách sử dụng thiếu cơ sở. Ở góc nhìn văn hóa, Kinh Dịch cũng là một di sản tư tưởng và biểu tượng có ảnh hưởng lớn ở Đông Á.", topic: "văn hóa Kinh Dịch" },
  { id: 42, category: "kinh-dich", question: "Kinh Dịch là gì?", answer: "Kinh Dịch thường được cho là bộ sách cổ của Trung Hoa giải thích về sự biến đổi của vũ trụ và vạn vật dựa trên Âm Dương và Bát quái. Trong dân gian, Kinh Dịch được ứng dụng rộng rãi vào việc dự đoán, chiêm quẻ và định hướng ứng xử.", topic: "tổng quan Kinh Dịch, Âm Dương, Bát quái" },
  { id: 43, category: "kinh-dich", question: "Tam đồng pháp là gì trong gieo quẻ?", answer: "Tam đồng pháp là phương pháp gieo quẻ Dịch phổ biến bằng cách tung 3 đồng tiền kim loại cổ cùng lúc. Tùy thuộc vào số lượng mặt ngửa (Dương) và mặt sấp (Âm) xuất hiện, người gieo sẽ xác định được hào âm, hào dương hay hào động.", topic: "tam đồng pháp, gieo quẻ tiền xu, hào âm hào dương" },
  { id: 44, category: "kinh-dich", question: "Quẻ Càn tượng trưng cho điều gì?", answer: "Quẻ Càn (Trời) thường tượng trưng cho năng lượng Dương mạnh mẽ, sự sáng tạo, sức mạnh, người cha hoặc người lãnh đạo. Trong chiêm quẻ, quẻ Càn hay phản ánh sự hanh thông, danh vọng nhưng cũng nhắc nhở tránh sự cứng nhắc, ngạo mạn.", topic: "quẻ Càn, Bát quái, năng lượng Dương" },
  { id: 45, category: "kinh-dich", question: "Quẻ Khôn tượng trưng cho điều gì?", answer: "Quẻ Khôn (Đất) tượng trưng cho tính Âm nhu, sự nâng đỡ, nhẫn nại, người mẹ và sự bao dung. Chiêm được quẻ Khôn thường mang ý nghĩa nên thuận theo tự nhiên, tích lũy nội lực và khiêm tốn thay vì hành động quá đường đột.", topic: "quẻ Khôn, Bát quái, tính Âm nhu" },
  { id: 46, category: "kinh-dich", question: "Thượng quẻ và Hạ quẻ là gì?", answer: "Mỗi quẻ Dịch gồm 6 hào được ghép từ 2 quẻ đơn (mỗi quẻ đơn có 3 hào). Quẻ nằm ở phía trên gọi là Thượng quẻ (hay Ngoại quẻ), còn quẻ nằm ở phía dưới gọi là Hạ quẻ (hay Nội quẻ).", topic: "Thượng quẻ, Hạ quẻ, cấu tạo quẻ Dịch" },
  { id: 47, category: "kinh-dich", question: "Quẻ Thần (hay quẻ Chủ) là gì?", answer: "Quẻ Chủ (hoặc Quẻ Bản) là quẻ đầu tiên thu được ngay sau khi thực hiện thao tác gieo quẻ. Quẻ này phản ánh trạng thái bối cảnh hiện tại và bản chất ban đầu của sự việc đang được câu hỏi đề cập.", topic: "quẻ chủ, quẻ bản, bối cảnh hiện tại" },
  { id: 48, category: "kinh-dich", question: "Quẻ Hỗ là gì và có ý nghĩa gì?", answer: "Quẻ Hỗ là quẻ phụ được tạo ra bằng cách lấy các hào 2, 3, 4 làm Hạ quẻ và hào 3, 4, 5 làm Thượng quẻ của quẻ gốc. Quẻ Hỗ thường phản ánh quá trình diễn biến ngầm hoặc nguyên nhân ẩn giấu bên trong sự việc.", topic: "quẻ Hỗ, diễn biến ngầm, cấu tạo hào" },
  { id: 49, category: "kinh-dich", question: "Sự khác biệt giữa Dương già và Dương trẻ?", answer: "Dương già (Lão Dương) là hào dương mang năng lượng biến đổi đỉnh điểm và sẽ chuyển thành hào âm (hào động). Dương trẻ (Thiếu Dương) là hào dương ổn định, giữ nguyên thuộc tính và không phát sinh sự biến đổi.", topic: "Lão Dương, Thiếu Dương, hào động" },
  { id: 50, category: "kinh-dich", question: "Sự khác biệt giữa Âm già và Âm trẻ?", answer: "Âm già (Lão Âm) là hào âm đạt mức biến động tối đa và sẽ chuyển sang hào dương (hào động). Âm trẻ (Thiếu Âm) là hào âm mang tính chất tĩnh, giữ nguyên trạng thái và không có sự biến đổi.", topic: "Lão Âm, Thiếu Âm, hào động" },
  { id: 51, category: "kinh-dich", question: "Gieo quẻ không có hào động nghĩa là gì?", answer: "Khi một quẻ gieo ra không có hào động nào, sự việc thường được cho là đang ở trạng thái ổn định hoặc duy trì đúng hiện trạng. Kết quả hoặc xu hướng của sự việc sẽ dựa chủ yếu vào ý nghĩa tổng quan của quẻ gốc.", topic: "quẻ không động, duy trì hiện trạng, quẻ tĩnh" },
  { id: 52, category: "kinh-dich", question: "Có nên gieo quẻ hộ người khác không?", answer: "Theo quan niệm dân gian, hoàn toàn có thể gieo quẻ hộ người khác nếu người đó thành tâm nhờ vả và có lý do chính đáng. Người gieo hộ cần tập trung tâm trí hướng về thông tin và hoàn cảnh của người được hỏi.", topic: "gieo quẻ hộ, chiêm quẻ giúp, tâm niệm gieo quẻ" },
  { id: 53, category: "kinh-dich", question: "Quẻ Lục Xung là gì?", answer: "Quẻ Lục Xung là quẻ có các cặp địa chi ở các hào tương ứng xung khắc trực tiếp với nhau. Quẻ này thường tượng trưng cho sự biến động nhanh chóng, mâu thuẫn hoặc giải tán, phù hợp với việc cần kết thúc nhanh nhưng bất lợi cho hợp tác lâu dài.", topic: "quẻ Lục Xung, xung khắc địa chi, biến động nhanh" },
  { id: 54, category: "kinh-dich", question: "Quẻ Lục Hợp là gì?", answer: "Quẻ Lục Hợp là quẻ có các địa chi ở các hào tương ứng hợp hòa với nhau. Quẻ này thường phản ánh sự gắn kết, hợp tác êm đẹp, hòa giải thành công hoặc các công việc mang tính bền vững dài lâu.", topic: "quẻ Lục Hợp, hòa hợp, hợp tác lâu dài" },
  { id: 55, category: "kinh-dich", question: "Trùng quẻ (quẻ Thuần) là gì?", answer: "Quẻ Thuần là quẻ Dịch được ghép từ hai quẻ đơn hoàn toàn giống nhau (như Thuần Càn, Thuần Khôn, Thuần Khảm...). Dân gian cho rằng quẻ Thuần thể hiện năng lượng của quẻ đó đạt mức rất cao và mang thuộc tính rất rõ nét.", topic: "quẻ Thuần, quẻ trùng, Bát quái" },
  { id: 56, category: "kinh-dich", question: "Phương pháp Mai Hoa Dịch Số là gì?", answer: "Mai Hoa Dịch Số thường được cho là phương pháp lập quẻ dựa vào các yếu tố tự nhiên như thời gian, con số, âm thanh hoặc hình ảnh quan sát được. Phương pháp này mang tính linh hoạt cao và không nhất thiết phải dùng dụng cụ gieo.", topic: "Mai Hoa Dịch Số, lập quẻ tự nhiên, đoán điềm" },
  { id: 57, category: "kinh-dich", question: "Sự khác nhau giữa Mai Hoa Dịch Số và Lục Hào?", answer: "Mai Hoa Dịch Số thường thiên về tượng quẻ và phản ứng nhanh theo thời điểm sự việc xảy ra. Trong khi đó, phương pháp Lục Hào đi sâu vào sự tương tác giữa Địa chi, Ngũ hành, Thế - Ứng và các Lục thân của 6 hào.", topic: "Mai Hoa Dịch Số, Lục Hào, so sánh phương pháp" },
  { id: 58, category: "kinh-dich", question: "Hào Thế và Hào Ứng là gì?", answer: "Trong phương pháp Lục Hào, Hào Thế đại diện cho bản thân người gieo hoặc chủ thể của câu hỏi. Hào Ứng tượng trưng cho đối tượng, môi trường, đối thủ hoặc kết quả của sự việc đang hướng tới.", topic: "Hào Thế, Hào Ứng, Lục Hào" },
  { id: 59, category: "kinh-dich", question: "Lục Thân trong Kinh Dịch gồm những gì?", answer: "Lục Thân là 5 mối quan hệ ngũ hành so với Hào Thế, gồm: Phụ mẫu, Huynh đệ, Tử túc, Thê tài, và Quan quỷ. Dân gian dùng Lục Thân để luận đoán các khía cạnh cụ thể như công danh, tiền bạc, gia đạo.", topic: "Lục Thân, Lục Hào, luận đoán khía cạnh" },
  { id: 60, category: "kinh-dich", question: "Hào Thê Tài tượng trưng cho điều gì?", answer: "Trong Lục Hào, hào Thê Tài thường tượng trưng cho tiền bạc, của cải, của ăn của để, tài sản kinh doanh hoặc người vợ/người yêu nữ trong mối quan hệ tình cảm.", topic: "hào Thê Tài, tài lộc, tình duyên nữ" },
  { id: 61, category: "kinh-dich", question: "Hào Quan Quỷ tượng trưng cho điều gì?", answer: "Hào Quan Quỷ thường đại diện cho công danh, sự nghiệp, chính quyền, pháp luật hoặc người chồng/người yêu nam. Ngoài ra, nó cũng có thể ám chỉ tai họa, bệnh tật nếu rơi vào trạng thái xấu.", topic: "hào Quan Quỷ, công danh, rủi ro" },
  { id: 62, category: "kinh-dich", question: "Hào Tử Túc tượng trưng cho điều gì?", answer: "Hào Tử Túc (hoặc Tử Tôn) thường tượng trưng cho con cái, thế hệ sau, sự giải tỏa lo âu, niềm vui, phúc lộc hoặc sản phẩm sáng tạo của con người.", topic: "hào Tử Túc, con cái, phúc đức" },
  { id: 63, category: "kinh-dich", question: "Hào Phụ Mẫu tượng trưng cho điều gì?", answer: "Hào Phụ Mẫu đại diện cho cha mẹ, thầy cô, giấy tờ, hợp đồng, nhà cửa, xe cộ hoặc các văn bằng chứng chỉ mang tính pháp lý.", topic: "hào Phụ Mẫu, giấy tờ, tài sản nhà đất" },
  { id: 64, category: "kinh-dich", question: "Hào Huynh Đệ tượng trưng cho điều gì?", answer: "Hào Huynh Đệ tượng trưng cho anh chị em, bạn bè, đồng nghiệp hoặc đối tác ngang hàng. Trong tài chính, hào này cũng thường ám chỉ sự hao tốn hoặc chi chia tài sản.", topic: "hào Huynh Đệ, bạn bè, hao tài" },
  { id: 65, category: "kinh-dich", question: "Thái Tuế trong luận quẻ có vai trò gì?", answer: "Thái Tuế là địa chi của năm hiện tại, được coi là vị thần tối cao quản lý năng lượng cả năm. Hào nào trùng hoặc được Thái Tuế trợ giúp sẽ mang sức mạnh và tầm ảnh hưởng rất lớn trong quẻ.", topic: "Thái Tuế, địa chi năm, Lục Hào" },
  { id: 66, category: "kinh-dich", question: "Nguyệt Kiến và Nhật Thần là gì?", answer: "Nguyệt Kiến là địa chi đại diện cho tháng, còn Nhật Thần là địa chi đại diện cho ngày gieo quẻ. Đây là hai yếu tố quan trọng nhất để xem xét độ vượng suy và tác động lực lên các hào.", topic: "Nguyệt Kiến, Nhật Thần, vượng suy hào" },
  { id: 67, category: "kinh-dich", question: "Hào Không Vong (Tuần Triệt Không Vong) là gì?", answer: "Hào rơi vào Tuần Triệt Không Vong thường được coi là trạng thái 'có mà như không', tạm thời chưa phát huy được tác dụng hoặc tượng trưng cho sự hư ảo, hoãn lại của sự việc.", topic: "Không Vong, hào trống rỗng, gián đoạn" },
  { id: 68, category: "kinh-dich", question: "Phản Ngâm và Phục Ngâm trong quẻ là gì?", answer: "Phản Ngâm là hiện tượng các hào biến đổi xung khắc ngược lại hào gốc, tượng trưng cho sự do dự, lặp đi lặp lại. Phục Ngâm là biến đổi trùng địa chi, phản ánh sự đình trệ, buồn phiền.", topic: "Phản Ngâm, Phục Ngâm, bế tắc do dự" },
  { id: 69, category: "kinh-dich", question: "Dùng ứng dụng gieo quẻ online có chuẩn không?", answer: "Theo quan niệm dân gian, yếu tố quyết định là sự tập trung tâm trí của người hỏi vào thời điểm lập quẻ. Thuật toán máy tính dựa trên thời gian thực vẫn có thể cho ra kết quả tham khảo nếu người gieo thực sự thành tâm.", topic: "gieo quẻ online, công nghệ, tâm niệm" },
  { id: 70, category: "kinh-dich", question: "Quẻ Thăng mang ý nghĩa tổng quan gì?", answer: "Quẻ Địa Phong Thăng thường tượng trưng cho sự tiến bước dần dần, tích lũy nội lực để vươn lên từng bước chắc chắn. Quẻ khuyên nên kiên nhẫn và tìm kiếm sự hỗ trợ từ người đi trước.", topic: "quẻ Thăng, tiến thủ, tích lũy" },
  { id: 71, category: "kinh-dich", question: "Quẻ Tụng mang ý nghĩa tổng quan gì?", answer: "Quẻ Thiên Thủy Tụng tượng trưng cho sự tranh chấp, bất đồng quan điểm hoặc kiện tụng. Khuyên người gặp quẻ này nên nhẫn nại, kiềm chế bản thân và chủ động hòa giải thay vì đẩy căng thẳng đi quá xa.", topic: "quẻ Tụng, tranh chấp, hòa giải" },
  { id: 72, category: "kinh-dich", question: "Quẻ Thái mang ý nghĩa gì?", answer: "Quẻ Địa Thiên Thái tượng trưng cho sự hòa hợp giữa Trời và Đất, khí Âm Dương giao hòa. Đây thường được coi là quẻ mang lại sự hanh thông, may mắn và phát triển thuận lợi.", topic: "quẻ Thái, hanh thông, hòa hợp" },
  { id: 73, category: "kinh-dich", question: "Quẻ Bĩ mang ý nghĩa gì?", answer: "Quẻ Thiên Địa Bĩ tượng trưng cho sự bế tắc, không thông suốt, khí Âm Dương tách biệt. Dân gian cho rằng khi gặp quẻ này nên thu nhiễm, giữ mình và chờ đợi thời cơ thuận lợi hơn.", topic: "quẻ Bĩ, bế tắc, kiên nhẫn" },
  { id: 74, category: "kinh-dich", question: "Quẻ Tiệm mang ý nghĩa gì?", answer: "Quẻ Phong Sơn Tiệm đại diện cho sự tiến triển từ từ, từng bước một như chim trĩ bay lên núi. Khuyên con người không nên nóng vội, làm tới đâu chắc tới đó.", topic: "quẻ Tiệm, tiến triển chậm, bền vững" },
  { id: 75, category: "kinh-dich", question: "Có thể thay đổi kết quả của một quẻ xấu không?", answer: "Dân gian tin rằng quẻ Dịch chỉ phản ánh xu hướng tự nhiên dựa trên hiện trạng. Khi biết trước nguy cơ, con người chủ động điều chỉnh thái độ, cách ứng xử và kế hoạch thì hoàn toàn có thể làm giảm thiểu tác động tiêu cực.", topic: "cải biến vận mệnh, ứng xử quẻ xấu, tích đức" },
  { id: 76, category: "kinh-dich", question: "Tại sao khi gieo quẻ cần giữ tâm thanh tịnh?", answer: "Kinh Dịch cho rằng tâm trí con người khi tĩnh lặng sẽ tạo ra sự tương thông với năng lượng tự nhiên xung quanh. Tâm thanh tịnh giúp thông tin phản ánh vào quẻ được chính xác, không bị nhiễu bởi sự lo âu hay tham vọng.", topic: "tâm thanh tịnh, cảm ứng, gieo quẻ" },
  // --- lich-am ---
  { id: 77, category: "lich-am", question: "Lịch âm là gì?", answer: "Lịch âm-dương truyền thống kết hợp chu kỳ Mặt Trăng với năm dương lịch để điều chỉnh mùa. Vì vậy cách gọi 'lịch âm' trong đời sống Việt Nam thường là lịch âm-dương, không phải lịch thuần âm.", topic: "lịch âm-dương" },
  { id: 78, category: "lich-am", question: "Một tháng âm lịch có bao nhiêu ngày?", answer: "Tháng âm thường có 29 hoặc 30 ngày. Việc có tháng 29 hay 30 ngày phụ thuộc chu kỳ trăng và quy tắc của lịch âm-dương.", topic: "tháng âm" },
  { id: 79, category: "lich-am", question: "Tháng nhuận là gì?", answer: "Tháng nhuận là tháng được thêm vào một số năm để lịch âm-dương không lệch quá xa với chu kỳ mùa của năm dương lịch. Năm có tháng nhuận có 13 tháng âm.", topic: "tháng nhuận" },
  { id: 80, category: "lich-am", question: "Năm nhuận âm có phải luôn nhuận tháng 4 không?", answer: "Không. Tháng được nhuận thay đổi theo từng năm dựa trên quy tắc lịch âm-dương. Vì vậy cần tra lịch của đúng năm thay vì ghi nhớ một tháng cố định.", topic: "năm nhuận" },
  { id: 81, category: "lich-am", question: "Ngày Hoàng đạo là gì?", answer: "Theo quan niệm dân gian, ngày Hoàng đạo là ngày có các thời thần được xem là thuận lợi cho một số việc. Mức độ phù hợp còn tùy việc và cách chọn ngày của từng trường phái.", topic: "Hoàng đạo" },
  { id: 82, category: "lich-am", question: "Ngày Hắc đạo là gì?", answer: "Hắc đạo là cách gọi những ngày được xem là kém thuận lợi trong một số hệ thống chọn ngày. Không nên hiểu rằng mọi việc làm trong ngày này đều chắc chắn xấu.", topic: "Hắc đạo" },
  { id: 83, category: "lich-am", question: "Giờ Hoàng đạo là gì?", answer: "Giờ Hoàng đạo là những khoảng giờ được dân gian xem là thuận lợi theo hệ thống thần sát của ngày. Người dùng thường kết hợp với tính chất công việc và các yếu tố khác khi chọn giờ.", topic: "giờ Hoàng đạo" },
  { id: 84, category: "lich-am", question: "Giờ Hắc đạo là gì?", answer: "Giờ Hắc đạo là những giờ được xem là kém thuận lợi theo cách tính truyền thống. Đây là quan niệm văn hóa, không phải kết luận khoa học về kết quả của công việc.", topic: "giờ Hắc đạo" },
  { id: 85, category: "lich-am", question: "Trực trong lịch là gì?", answer: "Trực là hệ thống 12 trực gồm Kiến, Trừ, Mãn, Bình, Định, Chấp, Phá, Nguy, Thành, Thu, Khai, Bế. Mỗi trực thường được gắn với nhóm công việc phù hợp theo quan niệm chọn ngày.", topic: "12 trực" },
  { id: 86, category: "lich-am", question: "Trực Thành thường được hiểu thế nào?", answer: "Trực Thành thường được xem là thuận cho một số việc có tính hoàn tất, xây dựng hoặc xác lập. Việc cụ thể vẫn nên xét thêm các yếu tố khác của ngày.", topic: "Trực Thành" },
  { id: 87, category: "lich-am", question: "Trực Phá có phải việc gì cũng xấu?", answer: "Không. Trực Phá thường được xem là không thuận cho một số việc cần ổn định lâu dài, nhưng lại có thể được dùng trong những việc mang tính phá bỏ hoặc loại bỏ theo một số quan niệm.", topic: "Trực Phá" },
  { id: 88, category: "lich-am", question: "Xem ngày cưới hỏi nên dựa vào gì?", answer: "Theo phong tục, người ta thường xét ngày, tháng, tuổi của cô dâu chú rể và đôi khi thêm giờ. Cách chọn cụ thể rất khác giữa vùng miền và trường phái nên không nên coi một tiêu chí là tuyệt đối.", topic: "xem ngày cưới" },
  { id: 89, category: "lich-am", question: "Xem ngày động thổ nên chú ý gì?", answer: "Dân gian thường xét ngày giờ, tuổi người đứng lễ và các yếu tố liên quan đến hướng hoặc công trình. Về thực tế, giấy phép, kết cấu và an toàn thi công vẫn quan trọng hơn.", topic: "động thổ" },
  { id: 90, category: "lich-am", question: "Xem ngày xuất hành là gì?", answer: "Đó là việc chọn thời điểm khởi hành được xem là thuận theo lịch truyền thống. Có thể kết hợp giờ, hướng và mục đích chuyến đi tùy trường phái.", topic: "xuất hành" },
  { id: 91, category: "lich-am", question: "Tuổi mụ được tính thế nào?", answer: "Theo cách tính dân gian, một người được tính là 1 tuổi ngay khi sinh và tăng thêm một tuổi vào dịp Tết. Vì vậy tuổi mụ thường lớn hơn tuổi dương một tuổi, nhưng cách tính có thể gây khác biệt quanh thời điểm sinh.", topic: "tuổi mụ" },
  { id: 92, category: "lich-am", question: "Người sinh trước hay sau Tết âm tính tuổi thế nào?", answer: "Trong cách tính tuổi dân gian, mốc năm âm lịch có thể dựa vào Tết hoặc mốc lập xuân tùy hệ thống. Khi tra mệnh lý cần xác định rõ phương pháp để tránh dùng lẫn hai cách.", topic: "mốc năm âm" },
  { id: 93, category: "lich-am", question: "Lập Xuân có phải là Tết âm lịch không?", answer: "Không. Tết Nguyên đán và Lập Xuân là hai mốc khác nhau trong lịch truyền thống. Một số trường phái mệnh lý dùng Lập Xuân làm mốc đổi năm khi lập lá số.", topic: "Lập Xuân" },
  { id: 94, category: "lich-am", question: "Ngày Can Chi là gì?", answer: "Ngày Can Chi được biểu thị bằng một Thiên Can kết hợp với một Địa Chi, tạo thành chu kỳ 60 ngày. Hệ thống này được dùng rộng rãi trong lịch truyền thống và mệnh lý.", topic: "Can Chi" },
  { id: 95, category: "lich-am", question: "Giờ Can Chi là gì?", answer: "Mỗi khoảng giờ trong ngày có thể được gán một Địa Chi và Thiên Can theo quy tắc truyền thống. Vì vậy giờ Can Chi không hoàn toàn trùng với cách chia giờ hành chính hiện đại.", topic: "giờ Can Chi" },
  { id: 96, category: "lich-am", question: "Ngày tốt có dùng cho mọi việc được không?", answer: "Không nhất thiết. Một ngày được xem là tốt tổng quát vẫn có thể không phù hợp với một việc cụ thể theo quan niệm chọn ngày. Nên xét mục đích trước rồi mới chọn tiêu chí phù hợp.", topic: "ngày tốt" },
  { id: 97, category: "lich-am", question: "Ngày xấu có phải tuyệt đối không nên làm gì?", answer: "Không. 'Xấu' trong lịch dân gian thường chỉ mức độ không thuận theo một hệ thống tiêu chí nhất định. Công việc thực tế vẫn cần căn cứ vào điều kiện, thời hạn và an toàn.", topic: "ngày xấu" },
  { id: 98, category: "lich-am", question: "Có nên xem ngày cưới theo tuổi cả hai người?", answer: "Theo phong tục, việc xem tuổi của cả hai thường được coi là quan trọng hơn chỉ xét một người. Tuy vậy mỗi gia đình hoặc trường phái có thể đặt trọng số khác nhau.", topic: "tuổi cưới hỏi" },
  { id: 99, category: "lich-am", question: "Xem ngày mua nhà có cần không?", answer: "Một số gia đình xem ngày ký hợp đồng, nhận nhà hoặc nhập trạch để tạo cảm giác an tâm về mặt phong tục. Đây là lựa chọn văn hóa, không thay thế việc kiểm tra pháp lý và chất lượng nhà.", topic: "mua nhà" },
  { id: 100, category: "lich-am", question: "Nhập trạch là gì?", answer: "Nhập trạch là nghi thức truyền thống khi gia chủ chuyển vào nơi ở mới. Nhiều gia đình chọn ngày giờ phù hợp theo lịch dân gian và chuẩn bị lễ nghi tùy phong tục.", topic: "nhập trạch" },
  { id: 101, category: "lich-am", question: "Ngày Sóc và Vọng là gì?", answer: "Sóc thường chỉ ngày đầu tháng âm lịch, còn Vọng thường chỉ ngày giữa tháng, tức ngày 15 âm lịch. Đây là các mốc quan trọng trong sinh hoạt và tín ngưỡng truyền thống.", topic: "Sóc Vọng" },
  { id: 102, category: "lich-am", question: "Tiết khí là gì?", answer: "Tiết khí chia chu kỳ năm theo vị trí tương đối của Mặt Trời thành 24 phần. Các tiết khí giúp liên hệ lịch với mùa vụ và cũng được sử dụng trong một số hệ thống mệnh lý.", topic: "24 tiết khí" },
  { id: 103, category: "lich-am", question: "Tại sao cùng một ngày nhưng app có thể cho kết quả khác nhau?", answer: "Các ứng dụng có thể dùng lịch nguồn, múi giờ, quy tắc Hoàng đạo hoặc trường phái chọn ngày khác nhau. Cần kiểm tra phương pháp tính trước khi so sánh.", topic: "múi giờ, thuật toán lịch" },
  { id: 104, category: "lich-am", question: "Múi giờ ảnh hưởng lịch Can Chi không?", answer: "Có thể ảnh hưởng, nhất là với thời điểm gần ranh giới giữa hai ngày hoặc giờ. Hệ thống tra cứu nên ghi rõ múi giờ và quy tắc đổi ngày đang sử dụng.", topic: "múi giờ" },
  { id: 105, category: "lich-am", question: "Có nên chọn ngày chỉ dựa vào Hoàng đạo?", answer: "Không nên nếu cần chọn ngày cho việc quan trọng. Theo cách tiếp cận dân gian, Hoàng đạo chỉ là một lớp thông tin; người dùng thường kết hợp thêm trực, Can Chi và tính chất công việc.", topic: "chọn ngày" },
  { id: 106, category: "lich-am", question: "Giờ tốt có quan trọng hơn ngày tốt không?", answer: "Tùy việc và trường phái. Một số cách chọn ngày coi giờ khởi sự là quan trọng, nhưng không có nguyên tắc chung rằng giờ luôn quan trọng hơn ngày.", topic: "ngày giờ tốt" },
  { id: 107, category: "lich-am", question: "Lịch Âm (Lịch Âm Dương) Việt Nam được tính như thế nào?", answer: "Lịch truyền thống Việt Nam thực chất là lịch Âm Dương, tính dựa trên chu kỳ mặt trăng quay quanh Trái Đất kết hợp với chu kỳ Trái Đất quay quanh Mặt Trời. Việc này giúp lịch vừa thể hiện được tuần trăng vừa sát với thời tiết các mùa nông nghiệp.", topic: "lịch Âm Dương, chu kỳ mặt trăng, tiết khí" },
  { id: 108, category: "lich-am", question: "Tháng nhuận là gì và vì sao lại có?", answer: "Một năm âm lịch ngắn hơn năm dương lịch khoảng 11 ngày. Để giữ cho lịch không bị lệch so với thời tiết bốn mùa, cứ khoảng 2 đến 3 năm người ta lại thêm một tháng nhuận vào lịch Âm Dương.", topic: "tháng nhuận, tính lịch âm, điều chỉnh tiết khí" },
  { id: 109, category: "lich-am", question: "Tuổi mụ được tính như thế nào?", answer: "Tuổi mụ (tuổi âm) thường được tính bằng cách lấy năm hiện tại trừ đi năm sinh rồi cộng thêm 1. Khoảng thời gian cộng thêm này tượng trưng cho 9 tháng 10 ngày thai nhi sinh sống trong bụng mẹ.", topic: "tuổi mụ, tính tuổi âm, phong tục dân gian" },
  { id: 110, category: "lich-am", question: "Trực trong ngày là gì?", answer: "Trực là hệ thống 12 trạng thái (Kiến, Trừ, Mãn, Bình, Định, Chấp, Phá, Nguy, Thành, Thâu, Khai, Bế) luân phiên quản lý từng ngày. Mỗi Trực sẽ phù hợp hoặc kiêng kỵ với những công việc nhất định.", topic: "12 Trực, xem ngày, Trực ngày" },
  { id: 111, category: "lich-am", question: "Ngày Tam Nương là những ngày nào?", answer: "Ngày Tam Nương là các ngày âm lịch: 3, 7, 13, 18, 22, 27 hằng tháng. Dân gian thường tránh khai trương, cưới hỏi hay làm việc đại sự vào các ngày này vì lo ngại xui xẻo.", topic: "ngày Tam Nương, kiêng kỵ, cưới hỏi" },
  { id: 112, category: "lich-am", question: "Ngày Nguyệt Kỵ là những ngày nào?", answer: "Dân gian có câu 'Mùng năm, mười bốn, hai ba / Làm gì cũng hỏng, chớ ra đường dài'. Đó là 3 ngày Nguyệt Kỵ (5, 14, 23 âm lịch) thường được khuyên hạn chế xuất hành xa hay khởi công.", topic: "ngày Nguyệt Kỵ, xuất hành, kiêng kỵ" },
  { id: 113, category: "lich-am", question: "Tiết khí là gì trong lịch âm?", answer: "Tiết khí là 24 điểm đặc trưng trên quỹ đạo Trái Đất quay quanh Mặt Trời, đại diện cho sự thay đổi thời tiết, khí hậu. Hệ thống tiết khí giúp bà con nông dân xác định chính xác thời vụ canh tác.", topic: "24 tiết khí, khí hậu, nông lịch" },
  { id: 114, category: "lich-am", question: "Cách tính giờ Địa chi trong ngày?", answer: "Một ngày đêm 24 giờ được chia đều cho 12 Địa chi, mỗi giờ Âm lịch tương ứng với 2 giờ Dương lịch (ví dụ: Giờ Tý từ 23h đêm trước đến 1h sáng, giờ Sửu từ 1h đến 3h sáng).", topic: "12 giờ địa chi, giờ Tý giờ Sửu, cách tính giờ" },
  { id: 115, category: "lich-am", question: "Sao Cửu Diệu niên hạn là gì?", answer: "Sao Cửu Diệu là hệ thống 9 vị sao (Thái Dương, Thái Âm, Mộc Đức, La Hầu, Kế Đô, Thái Bạch, Thổ Tú, Thủy Đức, Vân Hớn) luôn luân phiên chiếu mệnh mỗi người theo từng tuổi âm lịch.", topic: "Sao Cửu Diệu, sao chiếu mệnh, niên hạn" },
  { id: 116, category: "lich-am", question: "Thế nào là ngày Sát Chủ?", answer: "Ngày Sát Chủ là ngày được dân gian cho là mang năng lượng xung khắc mạnh, rất xấu đối với việc xây dựng, làm nhà, cưới hỏi hoặc tiến hành các nghi lễ quan trọng.", topic: "ngày Sát Chủ, kiêng kỵ xây dựng, xem ngày" },
  { id: 117, category: "lich-am", question: "Thế nào là ngày Thụ Tử?", answer: "Ngày Thụ Tử cũng thuộc nhóm ngày rất xấu trong quan niệm dân gian. Mọi người thường tránh mổ xẻ, chữa bệnh đại phẫu hoặc khởi sự quan trọng vào ngày này.", topic: "ngày Thụ Tử, đại kỵ, xem ngày lành" },
  { id: 118, category: "lich-am", question: "Chọn ngày động thổ cần chú ý những gì?", answer: "Khi chọn ngày động thổ, dân gian thường ưu tiên chọn ngày Hoàng Đạo, có Trực tốt (như Trực Kiến, Trực Thành), tránh các ngày Tam Nương, Nguyệt Kỵ, Sát Chủ và tuổi gia chủ không phạm Kim Lâu, Hoang Ốc.", topic: "ngày động thổ, làm nhà, Kim Lâu Hoang Ốc" },
  { id: 119, category: "lich-am", question: "Xem ngày cưới hỏi dựa trên yếu tố nào?", answer: "Xem ngày cưới hỏi thường căn cứ vào tuổi âm của cô dâu (tránh năm Kim Lâu), chọn các ngày Hoàng Đạo, ngày Hợp với tuổi hai vợ chồng và có các cát tinh chiếu hỗ trợ cho gia đạo.", topic: "xem ngày cưới, tuổi cô dâu, cát tinh" },
  { id: 120, category: "lich-am", question: "Hướng xuất hành đầu năm được tính như thế nào?", answer: "Hướng xuất hành thường được tính dựa vào Bát quái và Can Chi của ngày Mùng 1 Tết. Mọi người thường chọn hướng Hỷ Thần (mang lại niềm vui) hoặc Tài Thần (mang lại tài lộc).", topic: "hướng xuất hành, Hỷ Thần, Tài Thần" },
  { id: 121, category: "lich-am", question: "Giờ Tý bắt đầu từ mấy giờ?", answer: "Giờ Tý là khung giờ đầu tiên trong 12 giờ địa chi, bắt đầu từ 23h00 đêm hôm trước đến 01h00 sáng hôm sau. Khung thời gian từ 00h00 đến 01h00 được coi là chính Tý.", topic: "giờ Tý, khung giờ đêm, 12 địa chi" },
  { id: 122, category: "lich-am", question: "Trực Khai mang ý nghĩa gì?", answer: "Trực Khai tượng trưng cho sự mở đầu, bắt đầu một công việc mới. Ngày có Trực Khai rất phù hợp cho việc khai trương, bắt đầu học tập, ký kết hợp đồng hoặc xuất hành.", topic: "Trực Khai, khai trương, mở đầu" },
  { id: 123, category: "lich-am", question: "Trực Bế mang ý nghĩa gì?", answer: "Trực Bế tượng trưng cho sự đóng lại, khép kín. Dân gian thường tránh khởi công hay khai trương vào ngày này, nhưng lại phù hợp cho việc đắp đập, lấp hang lỗ hoặc xây tường bảo vệ.", topic: "Trực Bế, đóng khép, kiêng khởi công" },
  { id: 124, category: "lich-am", question: "Trực Phá mang ý nghĩa gì?", answer: "Trực Phá tượng trưng cho sự phá vỡ, dỡ bỏ. Ngày này thích hợp cho việc phá phá nhà cũ, dỡ bỏ công trình hư hỏng nhưng không thích hợp cho việc ký kết hay cưới hỏi.", topic: "Trực Phá, dỡ nhà, phá cũ" },
  { id: 125, category: "lich-am", question: "Trực Thành mang ý nghĩa gì?", answer: "Trực Thành tượng trưng cho sự thành công, hoàn thành. Dân gian đánh giá đây là ngày rất tốt để làm tiệc mừng, nhập trạch, cưới hỏi hoặc bắt đầu công việc mong muốn có kết quả tốt.", topic: "Trực Thành, thành công, nhập trạch" },
  { id: 126, category: "lich-am", question: "Năm nhuận âm lịch ảnh hưởng gì đến việc xem ngày?", answer: "Năm nhuận âm lịch có thêm một tháng nên việc tính tiết khí và chọn ngày cần căn cứ chính xác vào bảng lịch âm chính thống của năm đó để tránh nhầm lẫn giữa các tháng.", topic: "năm nhuận, tính tiết khí, bảng tra lịch" },
  { id: 127, category: "lich-am", question: "Làm sao để biết ngày tốt xuất hành?", answer: "Để chọn ngày xuất hành tốt, người ta thường kết hợp chọn ngày Hoàng Đạo, giờ Hoàng Đạo, hướng Tài Thần/Hỷ Thần và tránh các ngày xung khắc trực tiếp với bản mệnh gia chủ.", topic: "ngày xuất hành, Hỷ Thần, chọn giờ tốt" },
  { id: 128, category: "lich-am", question: "Ngày Nguyệt Tận là ngày nào?", answer: "Ngày Nguyệt Tận là ngày cuối cùng của tháng âm lịch (ngày 29 hoặc 30). Dân gian thường dùng ngày này để dọn dẹp, tổng kết và chuẩn bị đón năng lượng mới của tháng tiếp theo.", topic: "ngày Nguyệt Tận, cuối tháng âm, dọn dẹp" },
  { id: 129, category: "lich-am", question: "Giờ Dậu là mấy giờ?", answer: "Giờ Dậu là khoảng thời gian từ 17h00 chiều đến 19h00 tối. Đây là thời điểm hoàng hôn, mặt trời lặn và muông thú bắt đầu về tổ theo nhịp sinh học.", topic: "giờ Dậu, khung giờ chiều, 12 địa chi" },
  { id: 130, category: "lich-am", question: "Ngày Con Nước là gì?", answer: "Ngày Con Nước là những ngày nước thủy triều lên xuống mạnh trong tháng theo kinh nghiệm dân gian vùng sông nước. Người xưa khuyến cáo hạn chế đi lại sông nước vào các ngày này.", topic: "ngày Con Nước, thủy triều, kiêng sông nước" },
  { id: 131, category: "lich-am", question: "Cúng giao thừa vào giờ nào?", answer: "Lễ cúng giao thừa truyền thống luôn được tiến hành đúng vào giờ Chính Tý (từ 00h00 phút đêm Mùng 1 Tết), khoảnh khắc chuyển giao giữa năm cũ và năm mới.", topic: "cúng giao thừa, giờ Chính Tý, Tết truyền thống" },
  { id: 132, category: "lich-am", question: "Tại sao lịch âm Việt Nam đôi khi lệch 1 ngày so với Trung Quốc?", answer: "Sự lệch ngày này là do chênh lệch về múi giờ tiêu chuẩn (Việt Nam dùng UTC+7, Trung Quốc dùng UTC+8). Thời điểm xuất hiện điểm Sóc (trăng mới) rơi vào hai ngày khác nhau ở hai múi giờ.", topic: "múi giờ UTC+7, điểm Sóc, so sánh lịch âm" },
  { id: 133, category: "lich-am", question: "Mùng 1 đầu tháng âm lịch nên kiêng gì?", answer: "Theo quan niệm dân gian, ngày Mùng 1 âm lịch nên kiêng làm đổ vỡ đồ đạc, tránh tranh cãi, kiêng vay mượn tiền bạc và kiêng ăn một số thực phẩm mang tính xui xẻo để giữ năng lượng may mắn.", topic: "kiêng kỵ Mùng 1, phong tục đầu tháng, may mắn" },
  // --- menh-ly ---
  { id: 134, category: "menh-ly", question: "Ngũ hành gồm những gì?", answer: "Ngũ hành gồm Kim, Mộc, Thủy, Hỏa và Thổ. Theo quan niệm truyền thống, chúng biểu thị các nhóm tính chất và quan hệ tương sinh, tương khắc trong tự nhiên.", topic: "ngũ hành" },
  { id: 135, category: "menh-ly", question: "Tương sinh là gì?", answer: "Tương sinh mô tả quan hệ hỗ trợ theo vòng truyền thống: Mộc sinh Hỏa, Hỏa sinh Thổ, Thổ sinh Kim, Kim sinh Thủy, Thủy sinh Mộc. Đây là mô hình biểu tượng của hệ thống ngũ hành.", topic: "tương sinh" },
  { id: 136, category: "menh-ly", question: "Tương khắc là gì?", answer: "Tương khắc là quan hệ chế ước trong ngũ hành: Mộc khắc Thổ, Thổ khắc Thủy, Thủy khắc Hỏa, Hỏa khắc Kim, Kim khắc Mộc. Cách áp dụng cụ thể phụ thuộc hệ thống luận.", topic: "tương khắc" },
  { id: 137, category: "menh-ly", question: "Mệnh Kim hợp màu gì?", answer: "Theo ngũ hành dân gian, Kim thường được liên hệ với trắng, xám, bạc và có thể dùng nhóm màu Thổ như vàng, nâu để biểu trưng cho tương sinh. Đây là quy ước phong thủy, không phải quy luật khoa học.", topic: "mệnh Kim, màu sắc" },
  { id: 138, category: "menh-ly", question: "Mệnh Mộc hợp màu gì?", answer: "Mộc thường được liên hệ với xanh lá; một số cách luận thêm xanh dương hoặc đen của Thủy vì Thủy sinh Mộc. Mức độ phù hợp còn tùy hệ thống đang dùng.", topic: "mệnh Mộc, màu sắc" },
  { id: 139, category: "menh-ly", question: "Mệnh Thủy hợp màu gì?", answer: "Thủy thường gắn với xanh dương, đen; một số quan niệm bổ sung trắng, xám, bạc của Kim vì Kim sinh Thủy. Đây là cách quy ước dân gian.", topic: "mệnh Thủy, màu sắc" },
  { id: 140, category: "menh-ly", question: "Mệnh Hỏa hợp màu gì?", answer: "Hỏa thường gắn với đỏ, cam, hồng, tím; xanh lá đôi khi được xem là màu tương sinh vì Mộc sinh Hỏa. Nên hiểu đây là quan niệm ngũ hành về màu sắc.", topic: "mệnh Hỏa, màu sắc" },
  { id: 141, category: "menh-ly", question: "Mệnh Thổ hợp màu gì?", answer: "Thổ thường gắn với vàng, nâu; đỏ, cam, hồng, tím có thể được xem là nhóm tương sinh vì Hỏa sinh Thổ. Cách ứng dụng nên giữ ở mức tham khảo.", topic: "mệnh Thổ, màu sắc" },
  { id: 142, category: "menh-ly", question: "Nạp âm là gì?", answer: "Nạp âm là hệ thống gán một tên ngũ hành đặc thù cho từng cặp Can Chi trong chu kỳ 60. Nó khác với cách nói ngũ hành bản mệnh đơn giản và thường được dùng trong mệnh lý dân gian.", topic: "nạp âm" },
  { id: 143, category: "menh-ly", question: "Mệnh sinh theo năm sinh có phải nạp âm không?", answer: "Trong cách gọi phổ biến, 'mệnh theo năm sinh' thường chính là nạp âm của năm Can Chi. Tuy nhiên khi xem phong thủy còn có thể xét cung phi và nhiều lớp thông tin khác.", topic: "năm sinh, nạp âm" },
  { id: 144, category: "menh-ly", question: "Mệnh quái là gì?", answer: "Mệnh quái hay cung phi là hệ thống tính quái theo năm sinh và giới tính để phân nhóm Đông tứ hoặc Tây tứ. Nó thường được dùng khi xét hướng nhà, hướng giường hoặc hướng bàn.", topic: "mệnh quái" },
  { id: 145, category: "menh-ly", question: "Đông tứ mệnh là gì?", answer: "Đông tứ mệnh thường gồm các cung Khảm, Ly, Chấn và Tốn. Theo phong thủy Bát trạch, nhóm này được gắn với các hướng thuộc Đông tứ trạch.", topic: "Đông tứ mệnh" },
  { id: 146, category: "menh-ly", question: "Tây tứ mệnh là gì?", answer: "Tây tứ mệnh thường gồm Càn, Khôn, Cấn và Đoài. Theo Bát trạch, nhóm này được gắn với các hướng thuộc Tây tứ trạch.", topic: "Tây tứ mệnh" },
  { id: 147, category: "menh-ly", question: "Đông tứ trạch là gì?", answer: "Đông tứ trạch gồm các hướng Bắc, Nam, Đông và Đông Nam theo hệ thống Bát trạch. Đây là cách phân nhóm truyền thống để so sánh với Đông tứ mệnh.", topic: "Đông tứ trạch" },
  { id: 148, category: "menh-ly", question: "Tây tứ trạch là gì?", answer: "Tây tứ trạch gồm Tây, Tây Bắc, Tây Nam và Đông Bắc theo hệ thống Bát trạch. Việc áp dụng cần xác định đúng cung mệnh và hướng thực tế.", topic: "Tây tứ trạch" },
  { id: 149, category: "menh-ly", question: "Tuổi Tý hợp làm ăn với tuổi nào?", answer: "Trong quan niệm dân gian, Tý thường được xem có quan hệ tam hợp với Thìn và Thân, đồng thời thuộc nhóm lục xung với Ngọ. Tuy nhiên hợp tác thực tế còn phụ thuộc năng lực, vốn và mục tiêu.", topic: "tuổi Tý, tam hợp" },
  { id: 150, category: "menh-ly", question: "Tam hợp là gì?", answer: "Tam hợp là nhóm ba địa chi được dân gian xem có tính hỗ trợ tương đối: Thân-Tý-Thìn, Tỵ-Dậu-Sửu, Dần-Ngọ-Tuất, Hợi-Mão-Mùi. Đây là một lớp tham khảo trong mệnh lý.", topic: "tam hợp" },
  { id: 151, category: "menh-ly", question: "Tứ hành xung là gì?", answer: "Tứ hành xung là các nhóm địa chi được cho là có xu hướng xung đối trong một số hệ thống: Dần-Thân-Tỵ-Hợi; Thân-Tý-Mão-Ngọ; Tỵ-Hợi-Dần-Thân; và các nhóm thường được diễn giải khác nhau tùy trường phái. Không nên đồng nhất xung với 'chắc chắn xấu'.", topic: "tứ hành xung" },
  { id: 152, category: "menh-ly", question: "Lục xung là gì?", answer: "Lục xung chỉ sáu cặp địa chi đối xung: Tý-Ngọ, Sửu-Mùi, Dần-Thân, Mão-Dậu, Thìn-Tuất, Tỵ-Hợi. Đây chỉ là một yếu tố trong nhiều quan hệ Can Chi.", topic: "lục xung" },
  { id: 153, category: "menh-ly", question: "Vợ chồng khắc tuổi có sao không?", answer: "Theo dân gian, khắc tuổi có thể được xem là dấu hiệu cần chú ý, nhưng không có nghĩa hôn nhân chắc chắn bất hòa. Giao tiếp, trách nhiệm và hoàn cảnh thực tế thường quan trọng hơn một tiêu chí tuổi.", topic: "khắc tuổi vợ chồng" },
  { id: 154, category: "menh-ly", question: "Hai người cùng mệnh có chắc chắn hợp nhau không?", answer: "Không. Cùng một ngũ hành không tự động đồng nghĩa với mọi phương diện đều thuận. Cần phân biệt nạp âm, cung phi, Can Chi và hoàn cảnh cụ thể.", topic: "cùng mệnh" },
  { id: 155, category: "menh-ly", question: "Cung phi của nam và nữ có thể khác nhau không?", answer: "Có. Với cùng một năm sinh, cách tính cung phi thường cho kết quả khác giữa nam và nữ. Vì vậy tra cứu cần nhập đúng giới tính theo phương pháp đang sử dụng.", topic: "cung phi" },
  { id: 156, category: "menh-ly", question: "Sao hạn là gì?", answer: "Sao hạn là hệ thống dân gian dùng các sao và hạn theo tuổi để diễn giải những giai đoạn được cho là thuận hoặc cần thận trọng. Đây là tín ngưỡng dân gian, không phải dự báo khoa học.", topic: "sao hạn" },
  { id: 157, category: "menh-ly", question: "Sao Thái Bạch có đáng tin tuyệt đối không?", answer: "Không nên xem là dự báo chắc chắn. Trong dân gian, Thái Bạch thường được gắn với một số lưu ý về tài chính hoặc công việc, nhưng kết quả thực tế không thể được quyết định chỉ bởi sao hạn.", topic: "Thái Bạch" },
  { id: 158, category: "menh-ly", question: "Hạn Tam Tai là gì?", answer: "Tam Tai là khái niệm dân gian chỉ ba năm liên tiếp được cho là có tính thử thách đối với từng nhóm tuổi tam hợp. Đây là một hệ thống tín niệm và không nên dùng để kết luận chắc chắn về tương lai.", topic: "Tam Tai" },
  { id: 159, category: "menh-ly", question: "Kim Lâu là gì?", answer: "Kim Lâu là một cách tính tuổi dân gian, thường được nhắc khi xem tuổi làm nhà hoặc cưới hỏi. Có nhiều cách tính và cách áp dụng khác nhau nên cần ghi rõ trường phái.", topic: "Kim Lâu" },
  { id: 160, category: "menh-ly", question: "Hoang Ốc là gì?", answer: "Hoang Ốc là hệ thống vòng cung tuổi được dùng trong dân gian khi xem tuổi xây nhà. Một số cung được coi là thuận, một số cung không thuận theo quy tắc truyền thống.", topic: "Hoang Ốc" },
  { id: 161, category: "menh-ly", question: "Tuổi làm nhà có quan trọng hơn hướng nhà không?", answer: "Trong phong thủy dân gian, tuổi và hướng là hai nhóm thông tin khác nhau, không nên thay thế lẫn nhau. Với nhà ở thực tế, quy hoạch, khí hậu, kết cấu và công năng vẫn là yếu tố thiết yếu.", topic: "tuổi làm nhà" },
  { id: 162, category: "menh-ly", question: "Mệnh lý có phải khoa học không?", answer: "Mệnh lý dân gian là hệ thống văn hóa và niềm tin dựa trên Can Chi, ngũ hành, âm dương và các quy tắc truyền thống. Các dự đoán mệnh lý không được xem là phương pháp khoa học đã được chứng minh.", topic: "mệnh lý dân gian" },
  { id: 163, category: "menh-ly", question: "Mệnh Mộc kỵ màu gì?", answer: "Mệnh Mộc tương khắc với hành Kim, do đó dân gian khuyên người mệnh Mộc nên hạn chế sử dụng các sắc màu đại diện cho Kim như màu trắng, bạc, hoặc xám ánh kim.", topic: "mệnh Mộc, màu kỵ, Ngũ hành tương khắc" },
  { id: 164, category: "menh-ly", question: "Mệnh Thủy hợp với tuổi nào trong làm ăn?", answer: "Người mệnh Thủy thường thích hợp hợp tác với những người thuộc mệnh Kim (Kim sinh Thủy) hoặc người cùng mệnh Thủy để tạo sự tương trợ, tin tưởng lẫn nhau.", topic: "mệnh Thủy, hợp tuổi làm ăn, Kim sinh Thủy" },
  { id: 165, category: "menh-ly", question: "Mệnh Hỏa nên chọn xe màu gì?", answer: "Người mệnh Hỏa thích hợp chọn xe màu đỏ, hồng, tím (màu bản mệnh) hoặc màu xanh lá cây (hành Mộc tương sinh), giúp tạo cảm giác an tâm và may mắn khi di chuyển.", topic: "mệnh Hỏa, màu xe hợp, phong thủy xe" },
  { id: 166, category: "menh-ly", question: "Mệnh Thổ hợp phong thủy như thế nào?", answer: "Người mệnh Thổ hợp với không gian có màu đỏ, cam, nâu đất; thích hợp sử dụng đồ gốm sứ, đá tự nhiên và hạn chế đặt quá nhiều cây xanh rậm rạp (Mộc khắc Thổ) trong phòng ngủ.", topic: "mệnh Thổ, bài trí phong thủy, đá tự nhiên" },
  { id: 167, category: "menh-ly", question: "Cung phi Đông tứ mệnh bao gồm những cung nào?", answer: "Cung phi Nam mạng/Nữ mạng thuộc Đông tứ mệnh bao gồm 4 cung: Khảm, Tốn, Chấn, và Ly. Những người thuộc nhóm này hợp với các hướng Đông, Đông Nam, Nam và Bắc.", topic: "Cung phi, Đông tứ mệnh, hướng hợp" },
  { id: 168, category: "menh-ly", question: "Tây tứ mệnh bao gồm các cung nào?", answer: "Nhóm Tây tứ mệnh bao gồm 4 cung: Càn, Khôn, Cấn, và Đoài. Người thuộc nhóm Tây tứ mệnh thường thích hợp với các hướng Tây, Tây Bắc, Tây Nam và Đông Bắc.", topic: "Tây tứ mệnh, Cung phi, chọn hướng nhà" },
  { id: 169, category: "menh-ly", question: "Sao hạn hằng năm có đáng tin không?", answer: "Sao hạn là một nét văn hóa dân gian phản ánh tâm lý lo âu trước rủi ro. Việc cúng sao mang ý nghĩa cầu an giải tỏa tâm lý; quan trọng nhất vẫn là sống lành mạnh và cẩn trọng.", topic: "sao hạn, cúng sao giải hạn, an tâm" },
  { id: 170, category: "menh-ly", question: "Lục xung trong Can Chi là gì?", answer: "Lục xung là 6 cặp tuổi đối xung trực tiếp với nhau về địa chi: Tý - Ngọ, Sửu - Mùi, Dần - Thân, Mão - Dậu, Thìn - Tuất, Tỵ - Hợi. Dân gian cho rằng các cặp này dễ phát sinh mâu thuẫn.", topic: "Lục xung, xung khắc địa chi, Can Chi" },
  { id: 171, category: "menh-ly", question: "Sự khác nhau giữa Mệnh Cung Phi và Mệnh Niên?", answer: "Mệnh Niên dựa vào năm sinh (dùng chung cho nam nữ), còn Mệnh Cung Phi dựa trên Bát quái và giới tính. Mệnh Cung Phi thường dùng để xem hướng nhà, hướng bếp và phong thủy kiến trúc.", topic: "Mệnh Cung Phi, Mệnh Niên, chọn hướng nhà" },
  { id: 172, category: "menh-ly", question: "Thiên can Tương sinh Tương khắc là gì?", answer: "10 Thiên can (Giáp, Ất, Bính, Đinh, Mậu, Kỷ, Canh, Tân, Nhâm, Quý) có quan hệ sinh khắc dựa trên ngũ hành, ví dụ Giáp/Ất (Mộc) sinh Bính/Đinh (Hỏa) và khắc Mậu/Kỷ (Thổ).", topic: "Thiên can, sinh khắc Can Chi, Ngũ hành" },
  { id: 173, category: "menh-ly", question: "Tuổi Kim Lâu là gì?", answer: "Kim Lâu là hạn tuổi dân gian thường khuyên nên tránh khi làm các việc trọng đại như cưới hỏi (với nữ) hoặc làm nhà (với gia chủ), dựa trên cách tính chia dư cho 9.", topic: "tuổi Kim Lâu, kiêng cưới hỏi, kiêng làm nhà" },
  { id: 174, category: "menh-ly", question: "Hạn Hoang Ốc là gì?", answer: "Hoang Ốc nghĩa là nhà trống, hạn tuổi này dân gian khuyến cáo không nên tiến hành xây dựng, động thổ làm nhà để tránh ảnh hưởng tiêu cực đến sức khỏe và tài lộc.", topic: "hạn Hoang Ốc, xây nhà, kiêng kỵ động thổ" },
  { id: 175, category: "menh-ly", question: "Mệnh Hải Trung Kim có nghĩa là gì?", answer: "Hải Trung Kim có nghĩa là 'Vàng trong lòng biển'. Nạp âm này tượng trưng cho tiềm năng lớn ẩn giấu bên trong, cần sự kiên nhẫn và môi trường thích hợp để phát huy giá trị.", topic: "Hải Trung Kim, nạp âm mệnh Kim, tính cách" },
  { id: 176, category: "menh-ly", question: "Mệnh Lô Trung Hỏa mang đặc điểm gì?", answer: "Lô Trung Hỏa có nghĩa là 'Lửa trong lò'. Tượng trưng cho nguồn năng lượng nhiệt huyết, bùng cháy mạnh mẽ, có sức chịu đựng tốt nhưng đôi khi nóng tính.", topic: "Lô Trung Hỏa, nạp âm mệnh Hỏa, tính cách" },
  { id: 177, category: "menh-ly", question: "Mệnh Tùng Bách Mộc có ý nghĩa gì?", answer: "Tùng Bách Mộc nghĩa là 'Gỗ cây Tùng Bách'. Nạp âm này đại diện cho sự kiên cường, chí khí vươn lên vượt qua khó khăn thử thách, đáng tin cậy.", topic: "Tùng Bách Mộc, nạp âm mệnh Mộc, chí khí" },
  { id: 178, category: "menh-ly", question: "Thế nào là Ngũ hành Tương sinh?", answer: "Tương sinh là mối quan hệ hỗ trợ, thúc đẩy nhau phát triển: Mộc sinh Hỏa, Hỏa sinh Thổ, Thổ sinh Kim, Kim sinh Thủy, Thủy sinh Mộc.", topic: "Ngũ hành Tương sinh, hỗ trợ phát triển, phong thủy" },
  { id: 179, category: "menh-ly", question: "Thế nào là Ngũ hành Tương khắc?", answer: "Tương khắc là mối quan hệ ức chế, cản trở nhau: Mộc khắc Thổ, Thổ khắc Thủy, Thủy khắc Hỏa, Hỏa khắc Kim, Kim khắc Mộc.", topic: "Ngũ hành Tương khắc, kiềm chế, cân bằng" },
  { id: 180, category: "menh-ly", question: "Cách hóa giải xung khắc tuổi vợ chồng?", answer: "Dân gian thường hóa giải bằng cách chọn hướng nhà, hướng bếp hợp mệnh, sinh con hợp tuổi bố mẹ hoặc điều chỉnh không gian sống hòa hợp để tăng cường cát khí.", topic: "hóa giải xung khắc, hướng bếp, sinh con hợp tuổi" },
  { id: 181, category: "menh-ly", question: "Người mệnh Khảm thuộc nhóm mệnh nào?", answer: "Người có Mệnh Cung Phi là Khảm thuộc nhóm Đông tứ mệnh, hợp với các hướng Bắc (Phục Vị), Đông (Thiên Y), Đông Nam (Sinh Khí), Nam (Diên Niên).", topic: "Cung Khảm, Đông tứ mệnh, hướng hợp" },
  { id: 182, category: "menh-ly", question: "Thái Tuế phạm năm tuổi có sao không?", answer: "Năm phạm Thái Tuế (năm tuổi) dân gian cho rằng dễ gặp biến động trong công việc, tâm lý. Nên giữ sự bình tĩnh, hạn chế đầu tư mạo hiểm và chú ý sức khỏe.", topic: "Thái Tuế, năm tuổi, cẩn trọng biến động" },
  { id: 183, category: "menh-ly", question: "Đá phong thủy chọn theo Mệnh Niên hay Mệnh Cung Phi?", answer: "Khi chọn vật phẩm cá nhân đeo trên người (đá phong thủy, trang sức), dân gian thường ưu tiên căn cứ theo Mệnh Cung Phi để đảm bảo tính chính xác về năng lượng.", topic: "đá phong thủy, Mệnh Cung Phi, trang sức" },
  { id: 184, category: "menh-ly", question: "Tuổi Mão hợp màu gì năm 2026?", answer: "Tùy thuộc vào nạp âm cụ thể của từng tuổi Mão, tuy nhiên các màu thuộc hành Thủy (xanh dương, đen) và Mộc (xanh lá) thường mang lại sự nhẹ nhàng, ôn hòa.", topic: "tuổi Mão, màu sắc may mắn, phong thủy" },
  { id: 185, category: "menh-ly", question: "Làm sao để biết mình thuộc Mệnh Cung Phi nào?", answer: "Mệnh Cung Phi được tra cứu bằng bảng tổng hợp dựa trên năm sinh âm lịch và giới tính nam/nữ, tương ứng với 8 quẻ trong Bát quái.", topic: "tra cứu Cung Phi, Bát quái, năm sinh giới tính" },
];
